import numpy as np


def min_max_dist_dim3_14() -> np.ndarray:
    """Deterministic unrestricted packing search with diameter-constrained polish."""
    n = 14
    rng = np.random.default_rng(20260912)
    ii, jj = np.triu_indices(n, 1)
    m = len(ii)

    index = np.arange(n, dtype=float)
    z = 1.0 - 2.0 * (index + 0.5) / n
    golden = np.pi * (3.0 - np.sqrt(5.0))
    seed = np.column_stack((
        np.sqrt(1.0 - z * z) * np.cos(golden * index),
        np.sqrt(1.0 - z * z) * np.sin(golden * index),
        z,
    ))

    def distances2(x):
        d = x[ii] - x[jj]
        return np.einsum("ij,ij->i", d, d)

    def ratio(x):
        q = distances2(x)
        return float(q.min() / q.max())

    def normalize(x):
        x = np.asarray(x, dtype=float).reshape(n, 3).copy()
        x -= x.mean(axis=0, keepdims=True)
        qmax = distances2(x).max()
        if not np.isfinite(qmax) or qmax <= 0.0:
            return None
        x /= np.sqrt(qmax)
        return x if np.all(np.isfinite(x)) else None

    best = normalize(seed)
    best_value = ratio(best)

    for restart in range(8):
        if restart == 0:
            points = seed.copy()
        else:
            points = rng.normal(size=(n, 3))

        points = normalize(points)
        if points is None:
            continue

        for power in (2, 4, 8, 16):
            epsilon = 2.0e-3 / power
            for iteration in range(180):
                delta = points[ii] - points[jj]
                q = np.einsum("ij,ij->i", delta, delta)
                weight = -2.0 * power * (q + epsilon) ** (-power - 1)

                gradient = np.zeros_like(points)
                np.add.at(gradient, ii, weight[:, None] * delta)
                np.add.at(gradient, jj, -weight[:, None] * delta)

                scale = np.max(np.linalg.norm(gradient, axis=1))
                if not np.isfinite(scale) or scale <= 1.0e-14:
                    break

                learning_rate = 0.075 * (
                    1.0 - 0.55 * iteration / 179.0
                )
                points -= learning_rate * gradient / scale
                points = normalize(points)
                if points is None:
                    break

        if points is not None:
            value = ratio(points)
            if np.isfinite(value) and value > best_value:
                best = points.copy()
                best_value = value

    try:
        from scipy.optimize import minimize

        def constraints(v):
            x = v[:-1].reshape(n, 3)
            t = v[-1]
            q = distances2(x)
            return np.concatenate((q - t, 1.0 - q))

        def constraint_jacobian(v):
            x = v[:-1].reshape(n, 3)
            delta = x[ii] - x[jj]
            jac = np.zeros((2 * m, 3 * n + 1), dtype=float)
            rows = np.arange(m)
            for coord in range(3):
                jac[rows, 3 * ii + coord] = 2.0 * delta[:, coord]
                jac[rows, 3 * jj + coord] = -2.0 * delta[:, coord]
            jac[:m, -1] = -1.0
            jac[m:, :-1] = -jac[:m, :-1]
            return jac

        starts = [best.copy()]
        for scale in (0.004, 0.010):
            trial = normalize(best + scale * rng.normal(size=(n, 3)))
            if trial is not None:
                starts.append(trial)

        for start in starts:
            q = distances2(start)
            v0 = np.concatenate((start.ravel(), [float(q.min())]))
            result = minimize(
                lambda v: -v[-1],
                v0,
                method="SLSQP",
                jac=lambda v: np.r_[np.zeros(3 * n), -1.0],
                constraints={
                    "type": "ineq",
                    "fun": constraints,
                    "jac": constraint_jacobian,
                },
                bounds=[(None, None)] * (3 * n) + [(0.0, 1.0)],
                options={"maxiter": 350, "ftol": 1.0e-11, "disp": False},
            )

            if result.x is None or not np.all(np.isfinite(result.x)):
                continue

            candidate = normalize(result.x[:-1])
            if candidate is None:
                continue
            candidate_value = ratio(candidate)
            if np.isfinite(candidate_value) and candidate_value > best_value:
                best = candidate
                best_value = candidate_value
    except Exception:
        pass

    return np.asarray(best, dtype=float)

